function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function normaliseHash(value: unknown): string | null {
  return nonEmptyString(value) ? value.trim().toLowerCase() : null;
}

function isSupportedKind(value: unknown): value is CheckpointAttachmentKind {
  return typeof value === "string" && KIND_SET.has(value);
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value === "boolean" || typeof value === "string") {
    return JSON.stringify(value);
  }
  if (typeof value === "number") {
    return Number.isFinite(value) ? JSON.stringify(value) : "null";
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  if (isRecord(value)) {
    const entries = Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`);
    return `{${entries.join(",")}}`;
  }
  return "null";
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareRecovered(
  left: RecoveredCheckpointAttachment,
  right: RecoveredCheckpointAttachment,
): number {
  return (
    compareText(left.kind, right.kind) ||
    compareText(left.attachmentRef, right.attachmentRef) ||
    compareText(left.contentHash, right.contentHash) ||
    compareText(left.owner, right.owner)
  );
}

function compareStates(
  left: CheckpointAttachmentBindingState,
  right: CheckpointAttachmentBindingState,
): number {
  return (
    compareText(left.kind, right.kind) ||
    compareText(left.attachmentRef, right.attachmentRef) ||
    compareText(left.contentHash ?? "", right.contentHash ?? "") ||
    compareText(left.owner ?? "", right.owner ?? "") ||
    compareText(left.state, right.state)
  );
}

/**
 * Validates one binding without mutating it. The returned state is the repair
 * state that the binding must have; only `recovered` is eligible for output.
 */
export function validateCheckpointAttachmentBinding(
  binding: CheckpointAttachmentBinding,
  now: number = Date.now(),
): CheckpointAttachmentBindingState {
  const attachmentRef = nonEmptyString(binding?.attachmentRef)
    ? binding.attachmentRef
    : "";
  const kind = isSupportedKind(binding?.kind) ? binding.kind : "context";
  const rawHash = normaliseHash(binding?.contentHash);
  const owner = nonEmptyString(binding?.owner) ? binding.owner : null;
  const base = {
    attachmentRef,
    kind,
    contentHash: rawHash,
    owner,
  };

  if (binding?.contentHash === undefined || binding?.contentHash === null || binding?.contentHash === "") {
    return { ...base, state: "hash-missing" };
  }
  if (rawHash === null || !SHA256_HEX.test(rawHash)) {
    return { ...base, state: "hash-invalid" };
  }
  if (owner === null) {
    return { ...base, state: "owner-missing" };
  }

  const duration = binding.ttlMs ?? binding.ttl;
  const hasDuration = duration !== undefined;
  const hasExpiry = binding.expiresAtMs !== undefined;
  if (hasDuration && (typeof duration !== "number" || !Number.isFinite(duration) || duration < 0)) {
    return { ...base, state: "ttl-expired" };
  }
  if (hasExpiry && (typeof binding.expiresAtMs !== "number" || !Number.isFinite(binding.expiresAtMs))) {
    return { ...base, state: "ttl-expired" };
  }
  if (hasExpiry && binding.expiresAtMs <= now) {
    return { ...base, state: "ttl-expired" };
  }

  return { ...base, state: "recovered" };
}

/**
 * Recovers a checkpoint attachment set. This function is pure: it neither
 * changes the input nor executes attachment, recovery, or ledger side effects.
 * A repeated reference with a different hash is repaired as a conflict and
 * the first occurrence is retained. Identical reference/hash pairs are
 * deduplicated.
 */
export function recoverCheckpointAttachmentBindings(
  bindings: readonly CheckpointAttachmentBinding[],
  options: CheckpointAttachmentRecoveryOptions = {},
): CheckpointAttachmentRecoveryResult {
  const now = options.now ?? Date.now();
  const source = Array.isArray(bindings) ? bindings : [];
  const firstByRef = new Map<string, CheckpointAttachmentBinding>();
  const states: CheckpointAttachmentBindingState[] = [];
  const recovered: RecoveredCheckpointAttachment[] = [];

  for (const binding of source) {
    const validated = validateCheckpointAttachmentBinding(binding, now);
    const ref = validated.attachmentRef;
    const first = firstByRef.get(ref);

    if (first !== undefined) {
      const firstHash = normaliseHash(first.contentHash);
      const currentHash = validated.contentHash;
      if (firstHash !== currentHash) {
        states.push({ ...validated, state: "ref-conflict" });
      }
      // Equal reference/hash pairs are intentionally idempotent.
      continue;
    }

    firstByRef.set(ref, binding);
    states.push(validated);
    if (validated.state === "recovered") {
      const duration = binding.ttlMs ?? binding.ttl;
      recovered.push({
        attachmentRef: validated.attachmentRef,
        kind: validated.kind,
        contentHash: validated.contentHash as string,
        owner: validated.owner as string,
        ttlMs: typeof duration === "number" ? duration : null,
        expiresAtMs:
          typeof binding.expiresAtMs === "number" ? binding.expiresAtMs : null,
      });
    }
  }

  recovered.sort(compareRecovered);
  states.sort(compareStates);
  const digest = sha256(canonicalJson({ recovered, states }));
  return { recovered, states, digest };
}

export const recoverCheckpointAttachments = recoverCheckpointAttachmentBindings;

export function computeCheckpointAttachmentDigest(
  result: CheckpointAttachmentRecoveryResult,
): string {
  return sha256(
    canonicalJson({
      recovered: result.recovered,
      states: result.states,
    }),
  );
}

export function isCheckpointAttachmentKind(
  value: unknown,
): value is CheckpointAttachmentKind {
  return isSupportedKind(value);
}

export function isRecoveredCheckpointAttachment(
  value: unknown,
): value is RecoveredCheckpointAttachment {
  return (
    isRecord(value) &&
    nonEmptyString(value.attachmentRef) &&
    isSupportedKind(value.kind) &&
    typeof value.contentHash === "string" &&
    SHA256_HEX.test(value.contentHash) &&
    nonEmptyString(value.owner)
  );
}
"},{"path":"harness/specs/tasks/harness-gap-checkpoint-attachment-binding.md","content":"# Harness gap: checkpoint attachment binding (L04)

## Contract

Checkpoint attachments are restricted to exactly five kinds:

- `task-attachment`
- `recovery-instruction`
- `context`
- `external-artifact-ref`
- `ledger-checkpoint`

Arbitrary cursors and blobs are not checkpoint attachment kinds. Each binding carries an `attachmentRef`, `kind`, SHA-256 hex `contentHash`, non-empty `owner`, and a TTL (`ttlMs`/`ttl` duration or `expiresAtMs` absolute expiry).

## Recovery rules

Recovery is a pure function implemented by `recoverCheckpointAttachmentBindings` in `openclaw_runtime/src/runtime-core/checkpoint-attachment-binding.ts`.

1. A missing content hash produces `hash-missing`.
2. A malformed content hash produces `hash-invalid`.
3. A missing or empty owner produces `owner-missing`.
4. A malformed TTL or an expiry at/before the recovery time produces `ttl-expired`.
5. A repeated `attachmentRef` with a different hash produces `ref-conflict`; the first occurrence is retained.
6. A repeated `attachmentRef` with the same hash is deduplicated and does not produce another attachment.
7. Only bindings in the `recovered` state are returned in `recovered`.

The implementation does not mutate the input and does not execute attachment, recovery, ledger, or other side effects. The `now` option must be supplied in tests that require exact expiry behavior.

## Determinism

Recovered bindings and repair states are sorted by their stable identifying fields. The result contains a lowercase SHA-256 `digest` over the canonical JSON representation of `recovered` and `states`. Calling recovery twice with the same input and `now` returns the same ordering and digest. `computeCheckpointAttachmentDigest` independently recomputes the digest from a result.

## Examples

```ts
const hash = "a".repeat(64);
const result = recoverCheckpointAttachmentBindings(
  [
    { attachmentRef: "context/a", kind: "context", contentHash: hash, owner: "runtime", ttlMs: 60_000 },
    { attachmentRef: "context/a", kind: "context", contentHash: hash, owner: "runtime", ttlMs: 60_000 },
    { attachmentRef: "context/b", kind: "context", contentHash: hash, owner: "runtime", ttlMs: 60_000 },
  ],
  { now: 1_000 },
);

result.recovered.length === 1;
result.digest === computeCheckpointAttachmentDigest(result);
```

An invalid or conflicting binding is never silently accepted: it remains visible in `states` with the corresponding repair state and is absent from `recovered`.
