export const CHECKPOINT_ATTACHMENT_KINDS = [
  "task-attachment",
  "recovery-instruction",
  "context",
  "external-artifact-ref",
  "ledger-checkpoint",
] as const;

export type CheckpointAttachmentKind = (typeof CHECKPOINT_ATTACHMENT_KINDS)[number];

export type CheckpointAttachmentState =
  | "recovered"
  | "hash-missing"
  | "hash-invalid"
  | "owner-missing"
  | "ttl-expired"
  | "ref-conflict";

export interface CheckpointAttachmentBinding {
  attachmentRef: string;
  kind: CheckpointAttachmentKind;
  contentHash: string;
  owner: string;
  /** A duration in milliseconds. It is valid when finite and non-negative. */
  ttlMs?: number;
  /** An absolute expiry, in milliseconds since the Unix epoch. */
  expiresAtMs?: number;
  /** Alias accepted for callers that use `ttl` for the duration. */
  ttl?: number;
}

export interface CheckpointAttachmentRecoveryOptions {
  /** Recovery time. Supplying it makes expiry checks deterministic and repeatable. */
  now?: number;
}

export interface RecoveredCheckpointAttachment {
  attachmentRef: string;
  kind: CheckpointAttachmentKind;
  contentHash: string;
  owner: string;
  ttlMs: number | null;
  expiresAtMs: number | null;
}

export interface CheckpointAttachmentBindingState {
  attachmentRef: string;
  kind: CheckpointAttachmentKind;
  contentHash: string | null;
  owner: string | null;
  state: CheckpointAttachmentState;
}

export interface CheckpointAttachmentRecoveryResult {
  recovered: RecoveredCheckpointAttachment[];
  states: CheckpointAttachmentBindingState[];
  digest: string;
}

